        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
        vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, LLONG_MAX));
        for (int i = 1; i <= n; i++) dp[1][i] = prefix[i];
        for (int p = 2; p <= k; p++)
            for (int i = p; i <= n; i++)
                for (int j = p - 1; j < i; j++)
                    dp[p][i] = min(dp[p][i], max(dp[p - 1][j], prefix[i] - prefix[j]));
        return (int) dp[k][n];
    }
};

